function CustomerWorkPulse({
  customer,
  related = { leads: [], jobs: [], activity: [] },
  onSelectLead,
  onSelectJob,
}) {
  const safeRelated = {
    leads: Array.isArray(related?.leads) ? related.leads.filter((lead) => !lead.archivedAt) : [],
    jobs: Array.isArray(related?.jobs) ? related.jobs.filter((job) => !job.archivedAt) : [],
    activity: Array.isArray(related?.activity) ? related.activity : [],
  };
  const activeJobs = safeRelated.jobs.filter((job) => {
    const status = normalizeJobStatus(job.status || job.stage);
    return ["in_progress", "scheduled", "planned"].includes(status);
  });
  const readyJobs = safeRelated.jobs.filter((job) => normalizeJobStatus(job.status || job.stage) === "billing_ready");
  const dueLeads = safeRelated.leads.filter((lead) => isLeadFollowUpDue(lead));
  const primaryJob = activeJobs[0] || safeRelated.jobs[0] || null;
  const primaryLead = dueLeads[0] || safeRelated.leads[0] || null;
  const hasMissingContact = Boolean(customer && (!customer.phone || !customer.email));
  const contactLine = customer
    ? [customer.phone || "Phone not set", customer.email || "Email not set"].join(" / ")
    : "Select a customer to inspect contact readiness and linked field work.";
  const locationLine = customer
    ? [customer.company, customer.city, customer.serviceArea].filter(Boolean).join(" / ") || customer.id
    : "Customer work context appears here after an account is selected.";
  const nextAction = !customer
    ? "Choose an account from the work board"
    : hasMissingContact
      ? "Fill the contact gap before handoff"
      : dueLeads.length > 0
        ? "Follow up the active opportunity"
        : readyJobs.length > 0
          ? "Review ready work and proof status"
          : activeJobs.length > 0
            ? "Check the active job handoff"
            : "Keep account details ready for the next job";
  const pulseStats = [
    { label: "Active jobs", value: activeJobs.length, helper: "Scheduled or in progress" },
    { label: "Leads", value: safeRelated.leads.length, helper: dueLeads.length ? `${dueLeads.length} follow-up due` : "Pipeline records" },
    { label: "Ready work", value: readyJobs.length, helper: "Closeout candidates" },
    { label: "Activity", value: safeRelated.activity.length, helper: "Recent account context" },
  ];

  return (
    <section className="co-customers-pulse-card mx-auto w-full max-w-[1520px] px-5 pb-3 sm:px-6 lg:px-6" aria-label="Selected customer work pulse">
      <div className="co-customers-pulse-inner">
        <div className="co-customers-pulse-copy">
          <div className="flex min-w-0 flex-wrap items-center gap-2">
            <span className="co-customers-pulse-kicker">Customer Work Pulse</span>
            {customer ? <StatusBadge status={customerStatusText(customer)} /> : <Badge tone="slate">No account selected</Badge>}
            {hasMissingContact ? <Badge tone="amber">Contact gap</Badge> : null}
          </div>
          <h2>{customer?.name || "Select an account to review the work picture"}</h2>
          <p>{locationLine}</p>
          <p>{contactLine}</p>
          <div className="co-customers-pulse-next">
            <span>Next action</span>
            <strong>{nextAction}</strong>
          </div>
        </div>
        <div className="co-customers-pulse-actions" aria-label="Customer work shortcuts">
          <Button type="button" size="sm" variant="secondary" onClick={() => primaryLead ? onSelectLead(primaryLead.id) : undefined} disabled={!primaryLead}>
            Open Lead
          </Button>
          <Button type="button" size="sm" variant="secondary" onClick={() => primaryJob ? onSelectJob(primaryJob.id) : undefined} disabled={!primaryJob}>
            Open Job
          </Button>
        </div>
        <div className="co-customers-pulse-metrics">
          {pulseStats.map((stat) => (
            <div key={stat.label} className="co-customers-pulse-metric">
              <strong>{stat.value}</strong>
              <span>{stat.label}</span>
              <em>{stat.helper}</em>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

function customerEstimateRecords(customer, estimates = []) {
  if (!customer) return [];
  const normalizedName = String(customer.name || "").toLowerCase();
  return normalizeObjectArray(estimates).filter((estimate) => {
    const values = [
      estimate.customerId,
      estimate.customer?.id,
      estimate.customerName,
      estimate.customer,
      estimateDisplayCustomer?.(estimate),
    ].map((value) => String(value || "").toLowerCase());
    return values.includes(String(customer.id || "").toLowerCase()) || values.includes(normalizedName);
  });
}

function customerOperationsSummary(customer, { leads = [], jobs = [], activity = [], estimates = [] } = {}) {
  const related = relatedCustomerRecords(customer, leads, jobs, activity);
  const activeJobs = related.jobs.filter((job) => ["in_progress", "scheduled", "planned"].includes(normalizeJobStatus(job.status || job.stage)));
  const readyJobs = related.jobs.filter((job) => normalizeJobStatus(job.status || job.stage) === "billing_ready");
  const customerEstimates = customerEstimateRecords(customer, estimates);
  const openLeads = related.leads.filter((lead) => !lead.archivedAt && !["won", "lost", "closed"].includes(String(lead.status || "").toLowerCase()));
  const dueLeads = related.leads.filter((lead) => isLeadFollowUpDue(lead));
  const contactGap = Boolean(customer && (!customer.phone || !customer.email));
  const tone = contactGap || dueLeads.length ? "amber" : activeJobs.length || readyJobs.length ? "green" : openLeads.length || customerEstimates.length ? "orange" : "slate";
  const nextAction = contactGap
    ? "Fill contact gap"
    : dueLeads.length
      ? "Follow up lead"
      : readyJobs.length
        ? "Review ready work"
        : activeJobs.length
          ? "Check active job"
          : customerEstimates.length
            ? "Review estimate"
            : "Keep account ready";

  return {
    related,
    activeJobs,
    readyJobs,
    estimates: customerEstimates,
    openLeads,
    dueLeads,
    contactGap,
    tone,
    nextAction,
  };
}

function CustomerOperationsWorkbench({
  customers = [],
  selectedCustomer,
  leads = [],
  jobs = [],
  activity = [],
  estimates = [],
  canManage,
  onSelectCustomer,
  onSelectLead,
  onSelectJob,
  onCreateCustomer,
  onSetFilter,
}) {
  const activeRows = normalizeObjectArray(customers).filter((customer) => !customer.archivedAt);
  const customerSummaries = activeRows.map((customer) => ({ customer, summary: customerOperationsSummary(customer, { leads, jobs, activity, estimates }) }));
  const selectedSummary = customerOperationsSummary(selectedCustomer, { leads, jobs, activity, estimates });
  const queueRows = customerSummaries
    .sort((left, right) => Number(right.summary.contactGap) - Number(left.summary.contactGap)
      || right.summary.activeJobs.length - left.summary.activeJobs.length
      || right.summary.openLeads.length - left.summary.openLeads.length)
    .slice(0, 6);
  const focusCustomer = selectedCustomer || queueRows[0]?.customer || null;
  const focusSummary = selectedCustomer ? selectedSummary : queueRows[0]?.summary || customerOperationsSummary(null);
  const customerKpis = [
    { label: "Customers", value: customers.length, helper: "Visible accounts", tone: "blue", action: "View all", onClick: () => onSetFilter("All") },
    { label: "Active jobs", value: customerSummaries.reduce((sum, item) => sum + item.summary.activeJobs.length, 0), helper: "Customer work in motion", tone: "green", action: "Open jobs", onClick: () => onSelectJob(focusSummary.activeJobs[0]?.id) },
    { label: "Estimates", value: customerSummaries.reduce((sum, item) => sum + item.summary.estimates.length, 0), helper: "Proposal records", tone: "orange", action: "Review", onClick: () => onSetFilter("All") },
    { label: "Contact gaps", value: customerSummaries.filter((item) => item.summary.contactGap).length, helper: "Phone or email missing", tone: customerSummaries.some((item) => item.summary.contactGap) ? "amber" : "green", action: "Fix gaps", onClick: () => onSetFilter("All") },
  ];
  const pipelineSteps = [
    { label: "Customer", value: focusCustomer ? customerStatusText(focusCustomer) : "Select" },
    { label: "Lead", value: focusSummary.openLeads.length ? `${focusSummary.openLeads.length} open` : "None" },
    { label: "Estimate", value: focusSummary.estimates.length ? `${focusSummary.estimates.length} record${focusSummary.estimates.length === 1 ? "" : "s"}` : "None" },
    { label: "Job", value: focusSummary.activeJobs.length ? `${focusSummary.activeJobs.length} active` : focusSummary.related.jobs.length ? `${focusSummary.related.jobs.length} linked` : "None" },
    { label: "Proof", value: focusSummary.readyJobs.length ? "Ready work" : focusSummary.activeJobs.length ? "In progress" : "Pending" },
  ];

  return (
    <CommandPageFrame
      className="co-people-northstar-frame co-customers-northstar-frame"
      kpis={
        <div className="co-people-kpis">
          {customerKpis.map((item) => (
            <button key={item.label} type="button" className="co-people-kpi" data-tone={item.tone} onClick={item.onClick}>
              <span>{item.label}</span>
              <strong>{item.value}</strong>
              <em>{item.helper}</em>
              <b>{item.action}</b>
            </button>
          ))}
        </div>
      }
      rail={
        <AssistantRail
          eyebrow="Apex Assistant"
          title="Customers"
          description={focusCustomer ? `${focusCustomer.name}: ${focusSummary.nextAction}.` : "Select an account to inspect contact, pipeline, job, and proof context."}
          priorities={[
            { value: customerSummaries.filter((item) => item.summary.contactGap).length, label: "Contact gaps", tone: "amber" },
            { value: customerSummaries.reduce((sum, item) => sum + item.summary.openLeads.length, 0), label: "Open leads", tone: "orange" },
            { value: customerSummaries.reduce((sum, item) => sum + item.summary.activeJobs.length, 0), label: "Active jobs", tone: "green" },
            { value: customerSummaries.reduce((sum, item) => sum + item.summary.readyJobs.length, 0), label: "Ready work", tone: "green" },
          ]}
          actions={[
            { label: "Open lead", icon: "arrowUpRight", onClick: () => onSelectLead(focusSummary.openLeads[0]?.id), disabled: !focusSummary.openLeads[0] },
            { label: "Open job", icon: "briefcase", onClick: () => onSelectJob(focusSummary.activeJobs[0]?.id || focusSummary.related.jobs[0]?.id), disabled: !(focusSummary.activeJobs[0] || focusSummary.related.jobs[0]) },
            canManage ? { label: "New customer", icon: "plus", onClick: onCreateCustomer } : null,
          ].filter(Boolean)}
        />
      }
    >
      <section className="co-people-workbench" aria-label="Customer account command record">
        <div className="co-people-workbench-head">
          <div className="min-w-0">
            <p>Contractor account command</p>
            <h2>Customer, pipeline, work, proof, and next action</h2>
            <span>Accounts are operational records: contact readiness, active jobs, estimate context, and closeout work stay connected.</span>
          </div>
          <div className="co-people-workbench-actions">
            {canManage ? <Button type="button" onClick={onCreateCustomer}>New Customer</Button> : null}
            <Button type="button" variant="secondary" onClick={() => onSetFilter("Active")}>Active Accounts</Button>
          </div>
        </div>
        <div className="co-people-workbench-grid">
          <div className="co-people-record-queue">
            <div className="co-people-section-head">
              <span>Account queue</span>
              <strong>{queueRows.length || "Clear"}</strong>
            </div>
            {queueRows.length ? queueRows.map(({ customer, summary }) => (
              <WorkQueueCard
                key={customer.id}
                eyebrow={summary.contactGap ? "Contact gap" : summary.activeJobs.length ? "Active work" : summary.openLeads.length ? "Pipeline" : "Account"}
                title={customer.name || "Unnamed customer"}
                meta={[customer.company, customer.city || customer.serviceArea, customerContactText(customer)].filter(Boolean).join(" / ")}
                status={customerStatusText(customer)}
                tone={summary.tone}
                actionLabel={summary.nextAction}
                selected={focusCustomer?.id === customer.id}
                onClick={() => onSelectCustomer(customer.id)}
              >
                <div className="co-people-row-facts">
                  <span>Jobs <strong>{summary.related.jobs.length}</strong></span>
                  <span>Leads <strong>{summary.openLeads.length}</strong></span>
                  <span>Estimates <strong>{summary.estimates.length}</strong></span>
                  <span data-state={summary.contactGap ? "needs" : "ready"}>Contact <strong>{summary.contactGap ? "Gap" : "Ready"}</strong></span>
                </div>
              </WorkQueueCard>
            )) : (
              <div className="co-people-empty"><strong>No customer records visible</strong><span>Create or clear filters to build the account queue.</span></div>
            )}
          </div>

          <div className="co-people-selected-panel">
            <div className="co-people-section-head">
              <span>Selected account</span>
              <strong>{focusCustomer ? focusSummary.nextAction : "Waiting"}</strong>
            </div>
            {focusCustomer ? (
              <>
                <div className="co-people-selected-title">
                  <div className="min-w-0">
                    <h3>{focusCustomer.name}</h3>
                    <p>{[focusCustomer.company, focusCustomer.city, focusCustomer.serviceArea].filter(Boolean).join(" / ") || focusCustomer.id}</p>
                  </div>
                  <StatusBadge status={customerStatusText(focusCustomer)} />
                </div>
                <div className="co-people-proof-grid">
                  {pipelineSteps.map((step) => <span key={step.label}><em>{step.label}</em><strong>{step.value}</strong></span>)}
                </div>
                <div className="co-people-next-panel">
                  <span>Next action</span>
                  <strong>{focusSummary.nextAction}</strong>
                  <p>{customerContactText(focusCustomer)} / {focusSummary.related.activity.length} activity item{focusSummary.related.activity.length === 1 ? "" : "s"} linked.</p>
                </div>
                <div className="co-people-workbench-actions co-people-selected-actions">
                  <Button type="button" onClick={() => onSelectLead(focusSummary.openLeads[0]?.id)} disabled={!focusSummary.openLeads[0]}>Open Lead</Button>
                  <Button type="button" variant="secondary" onClick={() => onSelectJob(focusSummary.activeJobs[0]?.id || focusSummary.related.jobs[0]?.id)} disabled={!(focusSummary.activeJobs[0] || focusSummary.related.jobs[0])}>Open Job</Button>
                </div>
              </>
            ) : (
              <div className="co-people-empty"><strong>No customer selected</strong><span>Select a customer to inspect account operations.</span></div>
            )}
          </div>
        </div>
      </section>
    </CommandPageFrame>
  );
}

const COMMAND_CENTER_PRIORITY_ROW_LIMIT = 3;
const COMMAND_CENTER_LEAD_ROW_LIMIT = 2;
const COMMAND_CENTER_JOB_ROW_LIMIT = 4;

function CommandCenterPage({
  user,
  currentCompanyId,
  companyName,
  demoMode,
  leads,
  customers,
  estimates,
  contactHistory,
  jobs,
  leadSources,
  jobDraftImports,
  dailyReports,
  uploads,
  prePourChecklists,
  postPourChecklists,
  deliveryTickets,
  safetyIncidents,
  toolChecklists,
  timeEntries,
  changeOrderRequests,
  permissions,
  setActive,
  onSelectJob,
  onSelectImportedDraft,
  onSelectReport,
  onPrintDailyReport,
}) {
  const commandCenter = useMemo(() => deriveCommandCenterState({
    leads,
    customers,
    estimates,
    contactHistory,
    jobs,
    leadSources,
    jobDraftImports,
    dailyReports,
    uploads,
    prePourChecklists,
    postPourChecklists,
    deliveryTickets,
    safetyIncidents,
    toolChecklists,
    timeEntries,
    changeOrderRequests,
  }), [changeOrderRequests, contactHistory, customers, dailyReports, deliveryTickets, estimates, jobDraftImports, jobs, leadSources, leads, postPourChecklists, prePourChecklists, safetyIncidents, timeEntries, toolChecklists, uploads]);
  const fieldOpsAgent = useMemo(() => deriveFieldOpsAgentState({
    currentCompanyId,
    jobs,
    dailyReports,
    uploads,
    deliveryTickets,
    prePourChecklists,
    postPourChecklists,
    safetyIncidents,
    toolChecklists,
    timeEntries,
  }, {
    companyId: currentCompanyId,
    permissions,
    user,
  }), [currentCompanyId, dailyReports, deliveryTickets, jobs, permissions, postPourChecklists, prePourChecklists, safetyIncidents, timeEntries, toolChecklists, uploads, user]);

  function openModule(moduleId) {
    setActive?.(moduleId);
  }

  function openOwnerHealth() {
    openModule("appHealth");
  }

  function openJob(jobId) {
    if (jobId) onSelectJob?.(jobId);
  }

  function openImportedDraft(draftId) {
    if (draftId) onSelectImportedDraft?.(draftId);
  }

  function openFieldOpsItem(item = {}) {
    if (item.relatedJobId || (item.recordType === "job" && item.recordId)) {
      onSelectJob?.(item.relatedJobId || item.recordId);
    }
    openModule(item.moduleId || "jobs");
  }

  const canViewAppHealth = Boolean(permissions?.appHealth?.canView);
  const canViewWatchtower = Boolean(permissions?.watchtower?.canView);
  const canViewJobDraftImports = Boolean(permissions?.jobDraftImports?.canView);
  const canViewEstimates = Boolean(permissions?.estimates?.canView);
  const timeIssueCount = commandCenter.stats.timeIssues;
  const reportsUploadsDue = commandCenter.stats.openDailyReports + commandCenter.stats.dailyReportsNeedingReview + commandCenter.stats.jobsMissingPhotos;
  const operatingPlanCount = commandCenter.stats.scheduledTodayJobs
    + commandCenter.stats.scheduledTomorrowJobs
    + commandCenter.stats.jobsMissingCrew
    + commandCenter.stats.jobsMissingStartDate;
  const reviewApprovalCount = commandCenter.stats.reviewQueueItems;
  const billingReadinessCount = commandCenter.stats.jobsReadyToBill
    + (canViewEstimates ? commandCenter.stats.approvedEstimatesReadyToConvert : 0);
  const priorityStatCards = [
    {
      label: "Follow-Ups Due",
      value: commandCenter.stats.followUpsDueToday + commandCenter.stats.overdueFollowUps,
      helper: `${commandCenter.stats.overdueFollowUps} overdue / ${commandCenter.stats.followUpsDueToday} due today`,
      icon: "clock",
      tone: commandCenter.stats.overdueFollowUps > 0 ? "red" : "orange",
      actionLabel: "Open follow-up queue",
      onAction: () => openModule("leads"),
    },
    {
      label: "New Leads",
      value: commandCenter.stats.leadsNotContacted,
      helper: "Need initial contact or review",
      icon: "users",
      tone: "blue",
      actionLabel: "Open leads",
      onAction: () => openModule("leads"),
    },
    {
      label: "Jobs Needing Review",
      value: commandCenter.stats.jobsNeedingStartupReview + commandCenter.stats.jobsMissingCrew + commandCenter.stats.jobsMissingStartDate,
      helper: "Startup, crew, or schedule blockers",
      icon: "briefcase",
      tone: "amber",
      actionLabel: "Open jobs",
      onAction: () => openModule("jobs"),
    },
    {
      label: "Reports / Uploads Due",
      value: reportsUploadsDue,
      helper: "Reports needing review or photo evidence",
      icon: "upload",
      tone: "green",
      actionLabel: "Open reports",
      onAction: () => openModule("reports"),
    },
  ];
  function renderPriorityAction(label, onClick) {
    return (
      <button
        type="button"
        onClick={onClick}
        className="co-focus-ring inline-flex min-h-[2.05rem] items-center justify-between rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-xs font-black text-orange-700 shadow-[0_8px_18px_-18px_rgba(15,23,42,0.5)] transition hover:border-orange-300 hover:bg-orange-50 hover:text-orange-800"
      >
        {label}
        <span aria-hidden="true" className="ml-1">-&gt;</span>
      </button>
    );
  }

  const followUpPriority = (bucket) => ({
    overdue: 10,
    dueToday: 20,
    waiting: 50,
    followUpNeeded: 50,
    notContacted: 55,
  }[bucket] || 60);
  const priorityRows = [
    ...commandCenter.followUpQueue.items.map((item) => ({
      id: `followup-${item.id}`,
      priority: followUpPriority(item.bucket),
      eyebrow: FOLLOW_UP_QUEUE_GROUPS.find((group) => group.id === item.bucket)?.label || "Follow-Up",
      title: item.title,
      description: item.subtitle || item.reason,
      meta: `Last: ${item.lastContactedAt ? formatDateTime(item.lastContactedAt) : "not contacted"} / Next: ${item.nextFollowUpDate || "not scheduled"}`,
      tone: item.bucket === "overdue" ? "red" : item.bucket === "dueToday" ? "amber" : item.bucket === "waiting" ? "blue" : "orange",
      icon: item.bucket === "notContacted" ? "users" : item.bucket === "waiting" ? "clock" : "alert",
      badges: <Badge tone={item.bucket === "overdue" ? "red" : item.bucket === "dueToday" ? "amber" : "blue"}>{FOLLOW_UP_QUEUE_GROUPS.find((group) => group.id === item.bucket)?.label || "Follow-Up"}</Badge>,
      actions: renderPriorityAction(item.type === "leadSource" ? "Open Source Check" : "Open Follow-Up", () => openModule("leads")),
    })),
    ...commandCenter.importedDraftsNeedingCustomerMatch.map((draft) => ({
      id: `match-${draft.id}`,
      priority: 30,
      eyebrow: draft.customerMatchStatus || "Customer match",
      title: draft.customerName || draft.jobName || "Imported draft",
      description: draft.customerMatchReason || "Open the imported draft to confirm the customer or choose create-new.",
      tone: customerMatchStatusTone(draft.customerMatchStatus),
      icon: "database",
      badges: <Badge tone={customerMatchStatusTone(draft.customerMatchStatus)}>{draft.customerMatchStatus || "Needs Review"}</Badge>,
      actions: renderPriorityAction("Review Match", () => openImportedDraft(draft.id)),
    })),
    ...commandCenter.jobsNeedingStartupReview.map((job) => ({
      id: `startup-${job.id}`,
      priority: job.startupWarnings.length > 0 ? 40 : 45,
      eyebrow: job.customer || "Startup blocker",
      title: jobTitle(job),
      description: job.address || "Address pending",
      meta: `${job.startupWarnings.length} critical warning${job.startupWarnings.length === 1 ? "" : "s"}`,
      tone: job.startupWarnings.length > 0 ? "amber" : "slate",
      icon: job.startupWarnings.length > 0 ? "alert" : "briefcase",
      badges: <Badge tone={job.startupWarnings.length > 0 ? "amber" : "slate"}>{job.startupWarnings.length > 0 ? "Critical items missing" : job.startupStatus}</Badge>,
      actions: renderPriorityAction("Open Job", () => openJob(job.id)),
    })),
  ].sort((left, right) => left.priority - right.priority || String(left.title).localeCompare(String(right.title)));
  const visiblePriorityRows = priorityRows.slice(0, COMMAND_CENTER_PRIORITY_ROW_LIMIT);
  const topAlerts = [
    commandCenter.stats.overdueFollowUps > 0 ? { id: "overdue-followups", title: "Overdue follow-ups", description: `${commandCenter.stats.overdueFollowUps} manual outreach item${commandCenter.stats.overdueFollowUps === 1 ? "" : "s"} past due`, tone: "red", action: () => openModule("leads") } : null,
    commandCenter.stats.sourceChecksNeeded > 0 ? { id: "source-checks", title: "Lead source checks", description: `${commandCenter.stats.sourceChecksNeeded} source check${commandCenter.stats.sourceChecksNeeded === 1 ? "" : "s"} due or overdue`, tone: "amber", action: () => openModule("leads") } : null,
    reportsUploadsDue > 0 ? { id: "reports-uploads", title: "Reports / uploads due", description: `${reportsUploadsDue} report or photo evidence item${reportsUploadsDue === 1 ? "" : "s"} needs review`, tone: "amber", action: () => openModule("reports") } : null,
    commandCenter.stats.importedDraftsNeedingReview > 0 ? { id: "drafts", title: "Imported drafts", description: `${commandCenter.stats.importedDraftsNeedingReview} draft${commandCenter.stats.importedDraftsNeedingReview === 1 ? "" : "s"} waiting`, tone: "blue", action: () => openModule("jobDraftImports") } : null,
    timeIssueCount > 0 ? { id: "time", title: "Time issues", description: `${timeIssueCount} active or unassigned time ${timeIssueCount === 1 ? "entry" : "entries"}`, tone: "orange", action: () => openModule("time") } : null,
  ].filter(Boolean).slice(0, 5);
  const operationsPulseCards = [
    {
      title: "Operating Plan",
      value: operatingPlanCount,
      helper: "Today, tomorrow, and assignment readiness",
      icon: "briefcase",
      tone: operatingPlanCount ? "blue" : "slate",
      actionLabel: "Open schedule",
      onAction: () => openModule("schedule"),
      rows: [
        { label: "Today", value: commandCenter.stats.scheduledTodayJobs },
        { label: "Tomorrow", value: commandCenter.stats.scheduledTomorrowJobs },
        { label: "Unassigned", value: commandCenter.stats.jobsMissingCrew },
      ],
    },
    {
      title: "Field Execution",
      value: commandCenter.stats.fieldProofGaps,
      helper: "Reports, photos, tickets, safety, and checklist gaps",
      icon: "upload",
      tone: commandCenter.stats.fieldProofGaps ? "amber" : "green",
      actionLabel: "Open reports",
      onAction: () => openModule("reports"),
      rows: [
        { label: "Reports", value: commandCenter.stats.openDailyReports + commandCenter.stats.dailyReportsNeedingReview },
        { label: "Photos", value: commandCenter.stats.jobsMissingPhotos },
        { label: "Tickets", value: commandCenter.stats.pendingDeliveryTickets },
      ],
    },
    {
      title: "Review & Approve",
      value: reviewApprovalCount,
      helper: "Office decisions waiting before work moves forward",
      icon: "alert",
      tone: reviewApprovalCount ? "orange" : "green",
      actionLabel: "Open queue",
      onAction: () => openModule(commandCenter.stats.dailyReportsNeedingReview ? "reports" : "jobs"),
      rows: [
        { label: "Reports", value: commandCenter.stats.dailyReportsNeedingReview },
        { label: "Changes", value: commandCenter.stats.openChangeOrders },
        { label: "Safety", value: commandCenter.stats.openSafetyIncidents },
      ],
    },
    {
      title: "Billing Readiness",
      value: billingReadinessCount,
      helper: "Work ready to convert or move toward billing",
      icon: "check",
      tone: billingReadinessCount ? "green" : "slate",
      actionLabel: commandCenter.stats.jobsReadyToBill || !canViewEstimates ? "Open jobs" : "Open estimates",
      onAction: () => openModule(commandCenter.stats.jobsReadyToBill || !canViewEstimates ? "jobs" : "estimates"),
      rows: [
        { label: "Ready to bill", value: commandCenter.stats.jobsReadyToBill },
        canViewEstimates ? { label: "Approved", value: commandCenter.stats.approvedEstimatesReadyToConvert } : null,
        canViewEstimates ? { label: "Sent", value: commandCenter.stats.sentEstimatesWaiting } : null,
      ],
    },
  ];
  const commandHeaderMetrics = [
    {
      label: "Active Jobs",
      value: commandCenter.stats.activeJobs,
      helper: "Live job load",
      tone: "blue",
      icon: "briefcase",
    },
    {
      label: "Scheduled Today",
      value: commandCenter.stats.scheduledTodayJobs,
      helper: "Crew-ready work",
      tone: "green",
      icon: "calendar",
    },
    {
      label: "Reports / Photos",
      value: reportsUploadsDue,
      helper: "Evidence to review",
      tone: reportsUploadsDue ? "amber" : "slate",
      icon: "upload",
    },
    {
      label: "Money Ready",
      value: billingReadinessCount,
      helper: "Jobs or estimates ready",
      tone: billingReadinessCount ? "green" : "slate",
      icon: "check",
    },
  ];
  const demoPathSteps = [
    { label: "Command", helper: "Owner view", icon: "grid", moduleId: "commandCenter", enabled: true },
    { label: "Schedule", helper: "Today crew", icon: "calendar", moduleId: "schedule", enabled: true },
    { label: "Leads", helper: "Follow-up", icon: "users", moduleId: "leads", enabled: true },
    { label: "Estimates", helper: "Packet path", icon: "quote", moduleId: "estimates", enabled: canViewEstimates },
    { label: "Jobs", helper: "Field handoff", icon: "briefcase", moduleId: "jobs", enabled: true },
    { label: "Reports", helper: "Proof review", icon: "document", moduleId: "reports", enabled: true },
  ].filter((step) => step.enabled);
  const leadById = new Map((leads || []).map((lead) => [lead.id, lead]));
  const customerById = new Map((customers || []).map((customer) => [customer.id, customer]));
  const estimateById = new Map((estimates || []).map((estimate) => [estimate.id, estimate]));
  const followUpModuleByType = { lead: "leads", customer: "customers", estimate: "estimates" };
  const leadCommandRows = commandCenter.followUpQueue.items
    .filter((item) => item.type !== "leadSource")
    .slice(0, COMMAND_CENTER_LEAD_ROW_LIMIT)
    .map((item) => {
      const record = item.type === "lead" ? leadById.get(item.recordId) : item.type === "customer" ? customerById.get(item.recordId) : estimateById.get(item.recordId);
      const group = FOLLOW_UP_QUEUE_GROUPS.find((entry) => entry.id === item.bucket);
      const source = record?.source || record?.leadSource || record?.requestSource || (item.type === "estimate" ? "Estimate" : item.type === "customer" ? "Customer" : "Lead");
      const nextStep = record?.nextStep || item.reason || item.actionLabel || "Review follow-up";
      return {
        id: item.id,
        type: item.type,
        title: item.title || record?.customer || record?.name || record?.title || "Follow-up item",
        subtitle: item.subtitle || record?.city || record?.project || "Follow-up queue",
        source,
        lastContact: item.lastContactedAt ? formatDateTime(item.lastContactedAt) : "Not contacted",
        nextStep,
        status: group?.label || item.status || "Follow-Up",
        tone: item.bucket === "overdue" ? "red" : item.bucket === "dueToday" ? "amber" : item.bucket === "waiting" ? "blue" : "slate",
        actionLabel: item.actionLabel || "Open",
        moduleId: followUpModuleByType[item.type] || "leads",
      };
    });
  const missingReportJobIds = new Set(commandCenter.dailyReports.activeJobsMissingTodayReport.map((job) => job.id).filter(Boolean));
  const missingPhotoJobIds = new Set(commandCenter.uploads.jobsMissingPhotos.map((job) => job.id).filter(Boolean));
  const missingSetupByJobId = new Map(commandCenter.jobsMissingCrewOrStartDate.map((job) => [job.id, job]));
  const jobSnapshotById = new Map();
  [
    ...commandCenter.jobsNeedingStartupReview,
    ...commandCenter.schedule.scheduledTodayJobs,
    ...commandCenter.schedule.scheduledTomorrowJobs,
    ...commandCenter.jobsMissingCrewOrStartDate,
    ...commandCenter.dailyReports.activeJobsMissingTodayReport,
    ...commandCenter.uploads.jobsMissingPhotos,
  ].forEach((job) => {
    if (job?.id && !jobSnapshotById.has(job.id)) jobSnapshotById.set(job.id, job);
  });
  const jobSnapshotRows = Array.from(jobSnapshotById.values()).slice(0, COMMAND_CENTER_JOB_ROW_LIMIT).map((job) => {
    const setup = missingSetupByJobId.get(job.id) || {};
    const startupWarnings = Array.isArray(job.startupWarnings) ? job.startupWarnings : [];
    const missingReport = missingReportJobIds.has(job.id);
    const missingPhoto = missingPhotoJobIds.has(job.id);
    const startupStatus = job.startupStatus || "Not Started";
    const startupNeedsReview = startupWarnings.length > 0 || ["Not Started", "In Progress", "Needs Review"].includes(startupStatus);
    const nextAction = startupWarnings.length > 0
      ? `${startupWarnings.length} startup blocker${startupWarnings.length === 1 ? "" : "s"}`
      : setup.missingCrew || setup.missingStartDate
        ? [setup.missingCrew ? "Assign crew" : "", setup.missingStartDate ? "Set start date" : ""].filter(Boolean).join(" / ")
        : missingReport
          ? "Daily report"
          : missingPhoto
            ? "Upload photos"
            : jobNextStep(job);
    return {
      id: job.id,
      title: jobTitle(job),
      subtitle: job.customer || job.address || "Assigned site",
      phase: job.phase || jobStatusLabel(job.status || job.stage || "Not Started"),
      foreman: job.assignedForemanName || job.foremanName || job.foreman || job.crew || job.assignedUserName || "Unassigned",
      startupStatus,
      startupNeedsReview,
      missingReports: missingReport ? 1 : 0,
      missingPhotos: missingPhoto ? 1 : 0,
      nextAction,
    };
  });

  return (
    <div className="co-command-page">
      <div className="co-command-hero px-5 pb-1.5 pt-3 sm:px-6 lg:px-7">
        <div className="co-command-hero-head flex w-full flex-col gap-2 xl:flex-row xl:items-center xl:justify-between">
          <div className="min-w-0">
            <p className="text-[11px] font-black uppercase tracking-[0.24em] text-orange-700">{companyName || DEFAULT_COMPANY_NAME}</p>
            <h1 className="mt-0.5 break-words text-3xl font-black tracking-tight text-slate-950">Operations Command</h1>
            <p className="mt-0.5 max-w-3xl text-sm font-bold leading-5 text-slate-700">Today's owner/admin view for jobs, crews, field proof, follow-ups, and office review.</p>
          </div>
          <div className="co-command-hero-actions flex shrink-0 flex-wrap gap-2">
            <Button type="button" size="sm" onClick={() => openModule("leads")}><Icon name="users" />Start Priority Work</Button>
            <Button type="button" size="sm" variant="secondary" onClick={() => openModule("jobs")}><Icon name="briefcase" />Job Board</Button>
            {canViewAppHealth ? <Button type="button" size="sm" variant="secondary" onClick={openOwnerHealth}><Icon name="database" />App Health</Button> : null}
          </div>
        </div>
        <div className="co-command-header-metrics mt-3">
          {commandHeaderMetrics.map((metric) => (
            <div key={metric.label} className="co-command-header-metric" data-tone={metric.tone}>
              <span className="co-command-header-metric-icon" aria-hidden="true">
                <Icon name={metric.icon} className="h-4 w-4" />
              </span>
              <span className="min-w-0">
                <span className="co-command-header-metric-label">{metric.label}</span>
                <strong>{metric.value}</strong>
                <span className="co-command-header-metric-helper">{metric.helper}</span>
              </span>
            </div>
          ))}
        </div>
        {demoMode ? (
          <div className="co-command-demo-path mt-3" aria-label="Guided demo path">
            <div className="co-command-demo-path-copy">
              <strong className="co-command-demo-path-label">Demo path</strong>
              <span>Walk the first demo from owner command to field proof without jumping into unrelated setup.</span>
            </div>
            <div className="co-command-demo-path-actions">
              {demoPathSteps.map((step) => (
                <button
                  key={step.moduleId}
                  type="button"
                  className="co-command-demo-path-step co-focus-ring"
                  onClick={() => openModule(step.moduleId)}
                  aria-label={`Open ${step.label} demo step`}
                >
                  <Icon name={step.icon} className="h-4 w-4" />
                  <span>
                    <strong>{step.label}</strong>
                    <small>{step.helper}</small>
                  </span>
                </button>
              ))}
            </div>
          </div>
        ) : null}
      </div>
      <div className="co-command-workspace-grid grid w-full gap-2.5 px-5 pb-8 sm:px-6 lg:px-7">
        <CommandCenterMorningFlowCard
          onOpenLeads={() => openModule("leads")}
          onOpenDrafts={canViewJobDraftImports ? () => openModule("jobDraftImports") : null}
          onOpenJobs={() => openModule("jobs")}
          onOpenReports={() => openModule("reports")}
          priorityCount={priorityRows.length}
          overdueCount={commandCenter.stats.overdueFollowUps}
          jobsNeedingReview={commandCenter.stats.jobsNeedingStartupReview + commandCenter.stats.jobsMissingCrew + commandCenter.stats.jobsMissingStartDate}
          reportsUploadsDue={reportsUploadsDue}
        />
        <div className="co-command-ops-grid">
          {operationsPulseCards.map((card) => (
            <CommandCenterOpsPulseCard key={card.title} {...card} />
          ))}
        </div>
        <CommandCenterProofChainCard summary={commandCenter.proofChainSummary} onOpenModule={openModule} />
        <div className="co-command-kpi-grid grid grid-cols-2 gap-2.5 2xl:grid-cols-4">
          {priorityStatCards.map((card) => (
            <CommandCenterKpiCard key={card.label} item={card} />
          ))}
        </div>
        <div className="co-command-main-workbench grid items-start gap-2.5 2xl:grid-cols-[minmax(0,1fr)_23rem]">
          <div className="co-command-primary-stack grid min-w-0 gap-2.5">
            <CommandCenterSection
              title="Today's Priority Queue"
              description="The highest-priority office work, capped so the owner view stays scannable."
              count={priorityRows.length}
              emptyTitle="No priority office actions waiting"
              emptyDescription="Follow-ups, customer matches, and startup blockers will appear here when they need action."
              badgeTone="amber"
              compact
              footer={
                <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                  <p className="text-xs font-bold text-slate-700">
                    Showing {visiblePriorityRows.length} of {priorityRows.length} priority item{priorityRows.length === 1 ? "" : "s"}.
                  </p>
                  <Button type="button" size="sm" variant="ghost" onClick={() => openModule("leads")}>View all priority items</Button>
                </div>
              }
            >
              {visiblePriorityRows.map((row) => (
                <CommandCenterItem key={row.id} compact {...row} />
              ))}
            </CommandCenterSection>

            <CommandCenterTableCard
              title="Lead / Follow-Up Command"
              description="The top manual outreach work from leads, customers, and estimates."
              action={<Button type="button" size="sm" variant="ghost" onClick={() => openModule("leads")}>Open Follow-Up Queue</Button>}
              emptyText="No follow-up command rows waiting."
              className="co-command-leads-card"
            >
              {leadCommandRows.length ? (
                <>
                  <table className="co-command-table w-full min-w-[680px] text-left">
                    <thead>
                      <tr>
                        <th className="px-3 py-1">Lead / Company</th>
                        <th className="px-3 py-1">Source</th>
                        <th className="px-3 py-1">Last Contact</th>
                        <th className="px-3 py-1">Next Step</th>
                        <th className="px-3 py-1">Status</th>
                        <th className="px-3 py-1 text-right">Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {leadCommandRows.map((row) => (
                        <tr key={row.id} className="co-command-table-row align-middle">
                          <td className="px-3 py-1">
                            <p className="co-command-table-primary max-w-[16rem] truncate text-sm font-black">{row.title}</p>
                            <p className="co-command-table-secondary mt-0.5 max-w-[16rem] truncate text-xs font-bold">{row.subtitle}</p>
                          </td>
                          <td className="co-command-table-cell px-3 py-1 text-sm font-bold">{row.source}</td>
                          <td className="co-command-table-cell px-3 py-1 text-sm font-bold">{row.lastContact}</td>
                          <td className="px-3 py-1">
                            <p className="co-command-table-cell max-w-[18rem] truncate text-sm font-bold">{row.nextStep}</p>
                          </td>
                          <td className="px-3 py-1"><Badge tone={row.tone}>{row.status}</Badge></td>
                          <td className="px-3 py-1 text-right">
                            <button
                              type="button"
                              onClick={() => openModule(row.moduleId)}
                              className="co-command-table-action co-focus-ring"
                            >
                              {row.actionLabel}
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <div className="co-command-mobile-list">
                    {leadCommandRows.map((row) => (
                      <button key={row.id} type="button" onClick={() => openModule(row.moduleId)} className="co-command-mobile-row co-focus-ring">
                        <span className="min-w-0">
                          <span className="co-command-mobile-row-title">{row.title}</span>
                          <span className="co-command-mobile-row-subtitle">{row.subtitle}</span>
                          <span className="co-command-mobile-row-meta">{row.source} / {row.lastContact}</span>
                        </span>
                        <span className="co-command-mobile-row-side">
                          <Badge tone={row.tone}>{row.status}</Badge>
                          <span>{row.actionLabel}</span>
                        </span>
                      </button>
                    ))}
                  </div>
                </>
              ) : null}
            </CommandCenterTableCard>

            <CommandCenterTableCard
              title="Job Operations Snapshot"
              description="Startup blockers, report gaps, missing photos, and next job actions."
              action={<Button type="button" size="sm" variant="ghost" onClick={() => openModule("jobs")}>View all jobs</Button>}
              emptyText="Job operations look quiet."
              className="co-command-jobs-card"
            >
              {jobSnapshotRows.length ? (
                <>
                  <table className="co-command-table w-full min-w-[740px] text-left">
                    <thead>
                      <tr>
                        <th className="px-3 py-1">Job</th>
                        <th className="px-3 py-1">Phase</th>
                        <th className="px-3 py-1">Foreman</th>
                        <th className="px-3 py-1">Startup</th>
                        <th className="px-3 py-1">Reports</th>
                        <th className="px-3 py-1">Photos</th>
                        <th className="px-3 py-1">Next Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {jobSnapshotRows.map((row) => (
                        <tr key={row.id} className="co-command-table-row align-middle">
                          <td className="px-3 py-1">
                            <button type="button" onClick={() => openJob(row.id)} className="co-command-table-primary co-focus-ring block max-w-[17rem] truncate rounded-lg text-left text-sm font-black hover:text-orange-700">
                              {row.title}
                            </button>
                            <p className="co-command-table-secondary mt-0.5 max-w-[17rem] truncate text-xs font-bold">{row.subtitle}</p>
                          </td>
                          <td className="co-command-table-cell px-3 py-1 text-sm font-bold">{row.phase}</td>
                          <td className="co-command-table-cell px-3 py-1 text-sm font-bold">{row.foreman}</td>
                          <td className="px-3 py-1"><Badge tone={row.startupNeedsReview ? "amber" : "green"}>{row.startupNeedsReview ? "Yes" : "No"}</Badge></td>
                          <td className="px-3 py-1"><Badge tone={row.missingReports > 0 ? "amber" : "green"}>{row.missingReports}</Badge></td>
                          <td className="px-3 py-1"><Badge tone={row.missingPhotos > 0 ? "amber" : "green"}>{row.missingPhotos}</Badge></td>
                          <td className="px-3 py-1">
                            <p className="co-command-table-cell max-w-[16rem] truncate text-sm font-bold">{row.nextAction}</p>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <div className="co-command-mobile-list">
                    {jobSnapshotRows.map((row) => (
                      <button key={row.id} type="button" onClick={() => openJob(row.id)} className="co-command-mobile-row co-focus-ring">
                        <span className="min-w-0">
                          <span className="co-command-mobile-row-title">{row.title}</span>
                          <span className="co-command-mobile-row-subtitle">{row.subtitle}</span>
                          <span className="co-command-mobile-row-meta">{row.foreman} / {row.phase}</span>
                        </span>
                        <span className="co-command-mobile-row-side">
                          <Badge tone={row.startupNeedsReview ? "amber" : "green"}>{row.startupNeedsReview ? "Startup" : "Ready"}</Badge>
                          <span>{row.nextAction}</span>
                        </span>
                      </button>
                    ))}
                  </div>
                </>
              ) : null}
            </CommandCenterTableCard>
          </div>

          <div className="co-command-right-rail grid min-w-0 gap-1.5 xl:grid-cols-3 2xl:grid-cols-1">
            <FieldOpsAgentSummaryCard state={fieldOpsAgent} onOpenModule={openModule} onOpenItem={openFieldOpsItem} />
            {canViewWatchtower ? <CommandCenterWatchtowerCard actions={commandCenter.watchtowerActions} queue={commandCenter.watchtowerQueue} onOpenModule={openModule} /> : null}
            {canViewAppHealth ? <CommandCenterOwnerHealthCard onOpenOwnerHealth={openOwnerHealth} /> : null}

            <Card className="co-command-card p-2.5">
              <SectionHeader title="Quick Actions" />
              <div className="grid gap-1">
                <CommandCenterQuickAction icon="users" label="Open Follow-Up Queue" helper="Manual outreach work" onClick={() => openModule("leads")} />
                {canViewJobDraftImports ? <CommandCenterQuickAction icon="database" label="Review Imported Drafts" helper="Drafts and customer match" onClick={() => openModule("jobDraftImports")} /> : null}
                <CommandCenterQuickAction icon="briefcase" label="Open Jobs" helper="Startup, crews, and schedules" onClick={() => openModule("jobs")} />
                <CommandCenterQuickAction icon="document" label="Open Reports" helper="Daily report review" onClick={() => openModule("reports")} />
              </div>
            </Card>

            <Card className="co-command-card p-2.5">
              <SectionHeader title="Top Notifications / Alerts" description="Only the most actionable items stay in the rail." />
              <div className="grid gap-1">
                {topAlerts.length ? topAlerts.map((alert) => (
                  <button
                    type="button"
                    key={alert.id}
                    onClick={alert.action}
                    className="co-command-rail-row co-focus-ring grid w-full grid-cols-[0.55rem_minmax(0,1fr)_auto] items-start gap-2 rounded-xl border border-slate-200 bg-white px-2 py-1.5 text-left transition hover:border-orange-200 hover:bg-orange-50"
                  >
                    <span className="co-command-alert-dot mt-1.5" data-tone={alert.tone} aria-hidden="true" />
                    <span className="min-w-0">
                      <span className="block truncate text-sm font-black text-slate-950">{alert.title}</span>
                      <span className="mt-0.5 block text-xs font-bold leading-5 text-slate-600">{alert.description}</span>
                    </span>
                    <Badge tone={alert.tone}>Alert</Badge>
                  </button>
                )) : (
                  <div className="rounded-2xl border border-slate-100 bg-slate-50 px-3 py-3 text-sm font-bold text-slate-500">No top alerts right now.</div>
                )}
              </div>
              <p className="mt-3 text-xs font-bold text-slate-600">Use the bell in the top bar for the full notification center.</p>
            </Card>
          </div>
      </div>
    </div>
    </div>
  );
}

function OfficePilotWalkthroughCard({ onOpenCommandCenter, onOpenDrafts, onOpenJobs }) {
  const steps = [
    "Review imported drafts",
    "Match or create customer",
    "Create job",
    "Finish startup checklist",
    "Assign and send to field",
  ];

  return (
    <Card className="border-blue-200 bg-blue-50/80 p-4 shadow-sm">
      <div className="flex min-w-0 flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
        <div className="min-w-0">
          <Badge tone="blue">Pilot walkthrough</Badge>
          <h3 className="mt-2 text-base font-black text-slate-950">Run the office flow in order</h3>
          <p className="mt-1 text-sm leading-6 text-slate-700">
            For a new contractor walkthrough, start in Command Center and move one job from draft review to field-ready work.
          </p>
          <div className="mt-3 flex flex-wrap gap-2">
            {steps.map((step, index) => (
              <span key={step} className="rounded-full bg-white px-3 py-1.5 text-xs font-black text-blue-800 ring-1 ring-blue-100">
                {index + 1}. {step}
              </span>
            ))}
          </div>
        </div>
        <div className="flex shrink-0 flex-wrap gap-2">
          <Button type="button" size="sm" onClick={onOpenCommandCenter}>Open Command Center</Button>
          <Button type="button" size="sm" variant="secondary" onClick={onOpenDrafts}>Imported Drafts</Button>
          <Button type="button" size="sm" variant="secondary" onClick={onOpenJobs}>Jobs</Button>
        </div>
      </div>
    </Card>
  );
}

function DashboardCommandRailPolished({
  stats,
  selectedLead,
  selectedJob,
  liveJobsPreview,
  queueItems,
  activity,
  permissions,
  setActive,
  onFocusQueue,
  onFocusJobs,
  onFocusLeads,
}) {
  const activeQueueItems = normalizeObjectArray(queueItems).filter((item) => !item.archivedAt && !item.done);
  const activeJobs = normalizeObjectArray(liveJobsPreview).filter((job) => !job.archivedAt);
  const recentActivity = normalizeObjectArray(activity).slice(0, 1);
  const selectedLeadTitle = selectedLead?.customer || selectedLead?.company || "No lead selected";
  const selectedJobTitle = selectedJob ? jobTitle(selectedJob) : "No job selected";

  return (
    <div className="co-dashboard-right-rail min-w-0">
      <Card className="co-dashboard-rail-card p-4">
        <SectionHeader title="Operator Snapshot" description="Live readout for the daily workspace." />
        <div className="co-dashboard-rail-metrics">
          <div>
            <span>Active jobs</span>
            <strong>{activeJobs.length}</strong>
          </div>
          <div>
            <span>Queue open</span>
            <strong>{activeQueueItems.length}</strong>
          </div>
          <div>
            <span>Reports due</span>
            <strong>{stats.reportsDue || 0}</strong>
          </div>
          <div>
            <span>Pipeline</span>
            <strong>{currency(stats.pipelineValue || 0)}</strong>
          </div>
        </div>
      </Card>

      <Card className="co-dashboard-rail-card p-4">
        <SectionHeader title="Quick Moves" description="Jump without losing the board context." />
        <div className="co-dashboard-quick-moves-grid">
          {permissions?.jobs?.canManageAll ? (
            <button type="button" className="co-dashboard-action-row" onClick={() => setActive("commandCenter")}>
              <span>Command Center</span>
              <Icon name="settings" />
            </button>
          ) : null}
          <button type="button" className="co-dashboard-action-row" onClick={onFocusLeads}>
            <span>Lead pipeline</span>
            <Icon name="users" />
          </button>
          <button type="button" className="co-dashboard-action-row" onClick={onFocusJobs}>
            <span>Active jobs</span>
            <Icon name="briefcase" />
          </button>
          <button type="button" className="co-dashboard-action-row" onClick={onFocusQueue}>
            <span>Task queue</span>
            <Icon name="clipboard" />
          </button>
          {permissions?.reports?.canView ? (
            <button type="button" className="co-dashboard-action-row" onClick={() => setActive("reports")}>
              <span>Reports</span>
              <Icon name="document" />
            </button>
          ) : null}
        </div>
      </Card>

      <Card className="co-dashboard-rail-card p-4">
        <SectionHeader title="Selected Records" description="Current lead and job context stay visible while the board moves." />
        {selectedLead || selectedJob ? (
          <div className="co-dashboard-selected-stack">
            {selectedLead ? (
              <div className="co-dashboard-selected-record">
                <div className="flex min-w-0 items-start justify-between gap-3">
                  <div className="min-w-0">
                    <p>{selectedLeadTitle}</p>
                    <span>{selectedLead.project || selectedLead.city || "Project details pending"}</span>
                  </div>
                  <StatusBadge status={selectedLead.status || "New"} />
                </div>
                <div className="mt-3 flex flex-wrap gap-2">
                  <Badge tone={selectedLead.priority === "High" ? "amber" : "blue"}>{selectedLead.priority || "Normal"}</Badge>
                  <LeadScoreBadge lead={selectedLead} />
                </div>
                <button type="button" className="co-dashboard-inline-link" onClick={() => setActive("leads")}>Open full lead record</button>
              </div>
            ) : null}
            {selectedJob ? (
              <div className="co-dashboard-selected-record" data-kind="job">
                <div className="flex min-w-0 items-start justify-between gap-3">
                  <div className="min-w-0">
                    <p>{selectedJobTitle}</p>
                    <span>{[selectedJob.customer, jobScheduleLabel(selectedJob)].filter(Boolean).join(" / ") || "Schedule pending"}</span>
                  </div>
                  <StatusBadge status={jobStatusLabel(selectedJob.status || selectedJob.stage)} />
                </div>
                <div className="mt-3 flex flex-wrap gap-2">
                  <StartupStatusBadge status={selectedJob.startupStatus || "Not Started"} />
                  <Badge tone="blue">{Number(selectedJob.progress || 0)}% progress</Badge>
                </div>
                <button type="button" className="co-dashboard-inline-link" onClick={() => setActive("jobs")}>Open full job record</button>
              </div>
            ) : null}
          </div>
        ) : (
          <StateCard title="No record selected" description="Select a lead or job from the focus board to show its summary here." tone="slate" />
        )}
      </Card>

      <Card className="co-dashboard-rail-card p-4">
        <SectionHeader title="Recent Activity" description="Latest workspace movement." />
        <div className="grid gap-2">
          {recentActivity.length ? recentActivity.map((entry, index) => (
            <div key={entry.id || `${entry.type || "activity"}-${index}`} className="co-dashboard-activity-row">
              <span>{entry.title || entry.label || entry.type || "Activity"}</span>
              <p>{entry.description || entry.message || entry.detail || entry.timestamp || "Workspace update"}</p>
            </div>
          )) : (
            <div className="co-dashboard-activity-row">
              <span>No recent activity</span>
              <p>Activity appears here when records change.</p>
            </div>
          )}
        </div>
      </Card>
    </div>
  );
}

function DashboardPriorityCard({ item }) {
  return (
    <Card className="co-dashboard-priority-card" data-tone={item.tone || "orange"}>
      <div className="co-dashboard-priority-topline">
        <span className="co-dashboard-priority-icon">
          <Icon name={item.icon || "alert"} />
        </span>
        <Badge tone={item.tone || "orange"}>{item.badge}</Badge>
      </div>
      <div className="co-dashboard-priority-body">
        <p>{item.value}</p>
        <h3>{item.title}</h3>
        <span>{item.description}</span>
      </div>
      <div className="co-dashboard-priority-actions">
        <Button type="button" size="sm" onClick={item.onPrimary}>{item.primaryLabel}</Button>
        {item.secondaryLabel ? (
          <Button type="button" size="sm" variant="secondary" onClick={item.onSecondary}>{item.secondaryLabel}</Button>
        ) : null}
      </div>
    </Card>
  );
}

function DashboardOfficeQueueCard({
  items,
  openCount,
  onToggleTask,
  onArchiveTask,
  onOpenTools,
  disabled,
}) {
  const visibleItems = normalizeObjectArray(items).slice(0, 2);

  return (
    <Card className="co-dashboard-office-queue-card overflow-hidden">
      <div className="co-dashboard-board-header border-b border-slate-200 bg-white p-4">
        <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
          <div className="min-w-0">
            <h2>Office Queue</h2>
            <p>Today's queue stays visible, while full lead and task tools stay tucked into the operator drawer.</p>
          </div>
          <Button type="button" size="sm" onClick={onOpenTools}>Open queue tools</Button>
        </div>
      </div>
      <div className="co-dashboard-office-queue-list">
        {visibleItems.length ? visibleItems.map((item) => (
          <div key={item.id} className="co-dashboard-office-queue-row">
            <button type="button" onClick={() => onToggleTask?.(item.id)} disabled={disabled} className="co-dashboard-office-queue-check" aria-label={`Toggle ${item.title}`}>
              <Icon name="check" />
            </button>
            <div className="min-w-0">
              <p>{item.title}</p>
              <span>{item.meta || "Queue context pending"}</span>
            </div>
            <StatusBadge status={item.done ? "Done" : item.status} />
            <button type="button" className="co-dashboard-office-queue-archive" onClick={() => onArchiveTask?.(item.id)} disabled={disabled}>Archive</button>
          </div>
        )) : (
          <StateCard title="Queue is clear" description="New tasks, blockers, and due-today items will appear here." tone="slate" />
        )}
      </div>
      <div className="co-dashboard-board-footer">
        <p>Showing {visibleItems.length} of {openCount} active queue items</p>
        <Button type="button" size="sm" variant="secondary" onClick={onOpenTools}>Add or edit queue</Button>
      </div>
    </Card>
  );
}

function DashboardCockpitMetric({ label, value, helper, tone = "slate" }) {
  return (
    <div className="co-dashboard-cockpit-metric" data-tone={tone}>
      <span>{label}</span>
      <strong>{value}</strong>
      <small>{helper}</small>
    </div>
  );
}

function DashboardNextActionTile({ item }) {
  return (
    <button type="button" className="co-dashboard-next-tile" data-tone={item.tone || "orange"} onClick={item.onPrimary}>
      <span className="co-dashboard-next-icon"><Icon name={item.icon || "alert"} /></span>
      <span className="co-dashboard-next-copy">
        <em>{item.badge}</em>
        <strong>{item.title}</strong>
        <small>{item.description}</small>
      </span>
      <span className="co-dashboard-next-value">{item.value}</span>
    </button>
  );
}

function DashboardCockpitPanel({
  stats,
  pipelineValue,
  attentionCount,
  readyCount,
  openQueueCount,
  dashboardPriorityCards,
  permissions,
  setActive,
  onFocusLeads,
  onFocusJobs,
  onFocusQueue,
}) {
  return (
    <div className="co-dashboard-cockpit w-full min-w-0">
      <Card className="co-dashboard-cockpit-main">
        <div className="co-dashboard-cockpit-copy">
          <p>Owner command</p>
          <h2>Today's operating plan</h2>
          <span>{attentionCount ? `${attentionCount} items need a decision before the day moves. Clear the queue, protect active jobs, then move pipeline work.` : "The board is clear. Keep jobs moving and review ready work before opening deeper tools."}</span>
        </div>
        <div className="co-dashboard-cockpit-metrics">
          <DashboardCockpitMetric label="Needs action" value={attentionCount} helper="Reports, queue, startup" tone={attentionCount ? "orange" : "green"} />
          <DashboardCockpitMetric label="Ready work" value={readyCount} helper="Jobs and queue ready" tone="green" />
          <DashboardCockpitMetric label="Pipeline" value={compactCurrency(pipelineValue)} helper={`${stats.newLeads || 0} new leads`} tone="blue" />
          <DashboardCockpitMetric label="Queue open" value={openQueueCount} helper="Tasks still moving" tone={openQueueCount ? "amber" : "green"} />
        </div>
        <div className="co-dashboard-next-panel">
          <div className="co-dashboard-next-header">
            <span>Next moves</span>
            <strong>Click first</strong>
          </div>
          <div className="co-dashboard-next-grid">
            {dashboardPriorityCards.map((item) => <DashboardNextActionTile key={item.title} item={item} />)}
          </div>
        </div>
      </Card>
    </div>
  );
}

function DashboardFocusRow({ title, meta, detail, badge, selected, onClick }) {
  return (
    <button type="button" className={`co-dashboard-focus-row ${selected ? "is-selected" : ""}`} onClick={onClick}>
      <span className="min-w-0">
        <strong>{title}</strong>
        <small>{meta}</small>
        {detail ? <em>{detail}</em> : null}
      </span>
      {badge}
    </button>
  );
}

function DashboardDailyFocusBoard({
  leadRef,
  jobsRef,
  queueRef,
  visibleLeads,
  selectedLeadId,
  onSelectLead,
  liveJobsPreview,
  selectedJobId,
  onSelectJob,
  activeQueueItems,
  onToggleTask,
  onArchiveTask,
  onOpenLeads,
  onOpenJobs,
  onOpenTools,
  disabled,
}) {
  const leadRows = normalizeObjectArray(visibleLeads).slice(0, 4);
  const jobRows = normalizeObjectArray(liveJobsPreview).slice(0, 4);
  const queueRows = normalizeObjectArray(activeQueueItems).slice(0, 4);

  return (
    <Card className="co-dashboard-focus-board overflow-hidden">
      <div className="co-dashboard-board-header border-b border-slate-200 bg-white p-4">
        <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
          <div className="min-w-0">
            <h2>Daily Focus Board</h2>
            <p>Three operating lanes: sell the next job, protect active jobs, and clear today's office queue.</p>
          </div>
          <div className="co-dashboard-focus-actions">
            <Button type="button" size="sm" variant="secondary" onClick={onOpenLeads}>Open lead board</Button>
            <Button type="button" size="sm" variant="secondary" onClick={onOpenJobs}>Open job board</Button>
            <Button type="button" size="sm" onClick={onOpenTools}>Open queue tools</Button>
          </div>
        </div>
      </div>

      <div className="co-dashboard-focus-lanes">
        <section ref={leadRef} tabIndex={-1} className="co-dashboard-focus-lane">
          <div className="co-dashboard-focus-lane-header">
            <span>Lead follow-up</span>
            <Badge tone="blue">{leadRows.length} shown</Badge>
          </div>
          <div className="co-dashboard-focus-list">
            {leadRows.length ? leadRows.map((lead) => (
              <DashboardFocusRow
                key={lead.id}
                title={lead.customer || lead.company || "Unnamed lead"}
                meta={[lead.project, lead.city, leadSourceLabel(lead.source || "")].filter(Boolean).join(" / ")}
                detail={lead.nextStep || "Choose next follow-up"}
                selected={lead.id === selectedLeadId}
                onClick={() => onSelectLead(lead.id)}
                badge={<StatusBadge status={lead.status || "New"} />}
              />
            )) : (
              <StateCard title="No matching leads" description="Lead follow-up clears here when filters return no live work." tone="slate" />
            )}
          </div>
          <Button type="button" size="sm" variant="secondary" onClick={onOpenLeads}>Open lead board</Button>
        </section>

        <section ref={jobsRef} tabIndex={-1} className="co-dashboard-focus-lane">
          <div className="co-dashboard-focus-lane-header">
            <span>Jobs at risk</span>
            <Badge tone="orange">{jobRows.length} active</Badge>
          </div>
          <div className="co-dashboard-focus-list">
            {jobRows.length ? jobRows.map((job) => {
              const progressValue = Math.max(0, Math.min(100, Number(job.progress || 0)));
              return (
                <DashboardFocusRow
                  key={job.id}
                  title={jobTitle(job)}
                  meta={[job.customer, jobScheduleLabel(job)].filter(Boolean).join(" / ")}
                  detail={jobNextStep(job)}
                  selected={job.id === selectedJobId}
                  onClick={() => onSelectJob(job.id)}
                  badge={(
                    <span className="co-dashboard-focus-progress">
                      <span className="co-dashboard-focus-progress-track"><span style={{ width: `${progressValue}%` }} /></span>
                      <em>{progressValue}%</em>
                    </span>
                  )}
                />
              );
            }) : (
              <StateCard title="No active jobs" description="Active jobs appear here once they need schedule, crew, or startup attention." tone="slate" />
            )}
          </div>
          <Button type="button" size="sm" variant="secondary" onClick={onOpenJobs}>Open job board</Button>
        </section>

        <section ref={queueRef} tabIndex={-1} className="co-dashboard-focus-lane">
          <div className="co-dashboard-focus-lane-header">
            <span>Office queue</span>
            <Badge tone={queueRows.length ? "amber" : "green"}>{queueRows.length} shown</Badge>
          </div>
          <div className="co-dashboard-focus-list">
            {queueRows.length ? queueRows.map((item) => (
              <div key={item.id} className="co-dashboard-queue-focus-row">
                <button type="button" onClick={() => onToggleTask?.(item.id)} disabled={disabled} aria-label={`Toggle ${item.title}`}>
                  <Icon name="check" />
                </button>
                <span>
                  <strong>{item.title}</strong>
                  <small>{item.meta || "Queue context pending"}</small>
                </span>
                <span className="co-dashboard-queue-actions">
                  <StatusBadge status={item.done ? "Done" : item.status} />
                  <button type="button" onClick={() => onArchiveTask?.(item.id)} disabled={disabled}>Archive</button>
                </span>
              </div>
            )) : (
              <StateCard title="Queue clear" description="Due, blocked, and review items appear here when they need action." tone="green" />
            )}
          </div>
          <Button type="button" size="sm" variant="secondary" onClick={onOpenTools}>Open queue tools</Button>
        </section>
      </div>
    </Card>
  );
}

function DashboardPage(props) {
  const isOfficeWorkspace = Boolean(props.permissions?.jobs?.canManageAll || props.permissions?.leads?.canView);
  if (isOfficeWorkspace) {
    return <CommandCenterPage {...props} />;
  }
  return <DashboardPagePolished {...props} />;
}

function FirstOwnerOnboardingCard({ onboarding, onOpen, onOpenSupport }) {
  const steps = Array.isArray(onboarding?.steps) ? onboarding.steps : [];
  const nextStep = onboarding?.nextStep || steps.find((step) => !step.completed) || null;
  const guidedPlan = onboarding?.guidedPlan || {};
  const phases = Array.isArray(guidedPlan.phases) ? guidedPlan.phases : [];
  const nextActions = Array.isArray(guidedPlan.nextActions) ? guidedPlan.nextActions : steps.filter((step) => !step.completed).slice(0, 3);

  return (
    <Card className="overflow-hidden border-orange-100 bg-white">
      <div className="border-b border-orange-100 bg-orange-50/70 p-4">
        <div className="flex min-w-0 flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <Badge tone="orange">First owner setup</Badge>
              <Badge tone={onboarding?.percentComplete >= 80 ? "green" : "amber"}>{onboarding?.percentComplete || 0}% ready</Badge>
            </div>
            <h2 className="mt-2 text-lg font-black text-slate-950">Get this workspace ready for real work</h2>
            <p className="mt-1 text-sm font-bold leading-6 text-slate-600">
              Finish the first few setup actions so estimates, jobs, crews, and field workflows start from a clean operating base.
            </p>
          </div>
          {nextStep ? (
            <Button type="button" size="sm" onClick={() => onOpen?.(nextStep)}>
              {nextStep.actionLabel || "Continue setup"}
            </Button>
          ) : null}
        </div>
      </div>
      <div className="grid gap-3 border-b border-slate-100 bg-white p-4 lg:grid-cols-[minmax(0,0.95fr)_minmax(0,1.05fr)]">
        <div className="rounded-2xl border border-blue-100 bg-blue-50/70 p-4">
          <Badge tone="blue">Guided path</Badge>
          <h3 className="mt-2 break-words text-base font-black text-slate-950">{guidedPlan.headline || "Follow the setup path"}</h3>
          <p className="mt-1 break-words text-sm font-bold leading-6 text-slate-600">{guidedPlan.description || "Move through profile, team, first work, and rollout readiness in order."}</p>
          {nextActions.length ? (
            <div className="mt-3 flex flex-wrap gap-2">
              {nextActions.map((step, index) => (
                <Button key={step.key} type="button" size="sm" variant={index === 0 ? "primary" : "secondary"} onClick={() => onOpen?.(step)}>
                  {index + 1}. {step.actionLabel || step.label}
                </Button>
              ))}
            </div>
          ) : (
            <p className="mt-3 rounded-2xl border border-emerald-100 bg-emerald-50 px-3 py-2 text-sm font-black text-emerald-700">Setup is ready for managed use. Keep rollout readiness current before adding more users.</p>
          )}
        </div>
        <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4">
          {phases.map((phase) => (
            <button
              key={phase.id}
              type="button"
              disabled={!phase.actionStep}
              onClick={() => phase.actionStep ? onOpen?.(phase.actionStep) : null}
              className={`rounded-2xl border p-3 text-left transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500 focus-visible:ring-offset-2 ${phase.completed ? "border-emerald-100 bg-emerald-50/80" : "border-slate-200 bg-slate-50 hover:border-orange-200 hover:bg-orange-50"} ${phase.actionStep ? "" : "cursor-default"}`}
            >
              <span className="flex items-start justify-between gap-2">
                <span className="min-w-0">
                  <span className="block text-sm font-black text-slate-950">{phase.label}</span>
                  <span className="mt-1 block text-xs font-bold leading-4 text-slate-600">{phase.helper}</span>
                </span>
                <Badge tone={phase.completed ? "green" : "amber"}>{phase.completedCount}/{phase.totalCount}</Badge>
              </span>
            </button>
          ))}
        </div>
      </div>
      <div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-6">
        {steps.map((step) => {
          const isNextStep = nextStep?.key === step.key && !step.completed;
          return (
          <button
            key={step.key}
            type="button"
            className={`rounded-2xl border p-3 text-left transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-500 focus-visible:ring-offset-2 ${
              step.completed
                ? "border-emerald-100 bg-emerald-50/70 hover:border-emerald-200"
                : "border-orange-100 bg-white hover:border-orange-200 hover:bg-orange-50"
            }`}
            onClick={() => onOpen?.(step)}
          >
            <span className="mb-2 flex items-center justify-between gap-2">
              <span className="text-sm font-black text-slate-950">{step.label}</span>
              <Badge tone={step.completed ? "green" : isNextStep ? "amber" : "slate"}>{step.completed ? "Done" : isNextStep ? "Next" : "To do"}</Badge>
            </span>
            <span className="block text-xs font-bold leading-5 text-slate-600">{step.description}</span>
          </button>
          );
        })}
      </div>
      <div className="border-t border-slate-100 bg-slate-50/70 px-4 py-3">
        <div className="flex min-w-0 flex-col gap-3 md:flex-row md:items-center md:justify-between">
          <p className="text-sm font-bold leading-6 text-slate-600">
            Need help during setup? Open Support to copy a clean setup question with your workspace context.
          </p>
          <Button
            type="button"
            size="sm"
            variant="secondary"
            onClick={() => {
              if (typeof onOpenSupport === "function") {
                onOpenSupport(guidedPlan.supportWorkflow || "Setup / onboarding");
                return;
              }
              onOpen?.({ moduleId: "support" });
            }}
          >
            <Icon name="help" />Open Support
          </Button>
        </div>
      </div>
    </Card>
  );
}

