        <DashboardTodayWorkMetric label="Proof gaps" value={(stats.missingPhotos || 0) + (stats.openWorkflows || 0)} helper="Photos or workflow items" tone={(stats.missingPhotos || 0) + (stats.openWorkflows || 0) ? "amber" : "green"} />
